DROP TABLE IF EXISTS `tb_people`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_people` (
  `person_ID` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_ID` int NOT NULL,
  `courtesy_title` varchar(50) DEFAULT NULL,
  `given_names` varchar(150) NOT NULL,
  `family_names` varchar(150) NOT NULL,
  `birth_date` date DEFAULT NULL,
  `gender` enum('Hombre','Mujer','Prefiero no decirlo','M','F','Other','Masculino','Femenino','Otro','No especificado') DEFAULT NULL,
  `country_code` char(2) DEFAULT 'MX',
  `phone` varchar(25) DEFAULT NULL,
  `status` bit(1) NOT NULL DEFAULT b'1',
  `creation_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `last_update` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`person_ID`),
  KEY `idx_people_user` (`user_ID`),
  CONSTRAINT `fk_people_user` FOREIGN KEY (`user_ID`) REFERENCES `tb_users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=7501 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
