/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_people_after_update` AFTER UPDATE ON `tb_people` FOR EACH ROW BEGIN
    INSERT INTO `tb_logs` (`table_name`, `table_operation`, `db_user`, `operation_date`, `table_description`, `operation_status`)
    VALUES ('tb_people', 'Update', USER(), NOW(),
            CONCAT('Persona modificada. ID=', NEW.person_ID, ' | nombre: ', OLD.given_names, ' ', OLD.family_names, ' -> ', NEW.given_names, ' ', NEW.family_names, ' | phone: ', COALESCE(OLD.phone, 'NULL'), ' -> ', COALESCE(NEW.phone, 'NULL'), ' | status: ', CAST(OLD.status AS UNSIGNED), ' -> ', CAST(NEW.status AS UNSIGNED)), b'1');
END */;;
DELIMITER ;
