CREATE DEFINER=`root`@`localhost` FUNCTION `fn_calcular_edad`(p_fecha_nac DATE) RETURNS int
    NO SQL
    DETERMINISTIC
BEGIN
    IF p_fecha_nac IS NULL THEN
        RETURN NULL;
    END IF;
    RETURN TIMESTAMPDIFF(YEAR, p_fecha_nac, CURDATE());
END ;;
