CREATE DEFINER=`root`@`localhost` FUNCTION `fn_elemento_aleatorio`(p_lista TEXT, p_total_elementos INT) RETURNS varchar(100) CHARSET utf8mb4
    NO SQL
BEGIN
    DECLARE v_indice INT;
    SET v_indice = fn_entero_aleatorio(1, p_total_elementos);
