CREATE DEFINER=`root`@`localhost` FUNCTION `fn_estatus_probabilistico`(p_prob_activo INT) RETURNS bit(1)
    NO SQL
BEGIN
    IF (RAND() * 100) < p_prob_activo THEN
        RETURN b'1';
    ELSE
        RETURN b'0';
    END IF;
END ;;
