CREATE DEFINER=`root`@`localhost` FUNCTION `fn_verificar_stock`(p_product_id INT UNSIGNED, p_cantidad INT UNSIGNED) RETURNS bit(1)
    READS SQL DATA
BEGIN
    DECLARE v_stock INT DEFAULT 0;
    DECLARE v_estatus BIT(1) DEFAULT b'0';

    SELECT `current_stock`, `status`
    INTO v_stock, v_estatus
    FROM `tb_products`
    WHERE `ID` = p_product_id;

    IF v_estatus = b'1' AND v_stock >= p_cantidad THEN
        RETURN b'1';
    ELSE
        RETURN b'0';
    END IF;
END ;;
DELIMITER ;
