CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_registrar_producto_categoria`(
    IN p_sku VARCHAR(50),
    IN p_nombre VARCHAR(150),
    IN p_descripcion TEXT,
    IN p_precio DECIMAL(12,2),
    IN p_stock INT UNSIGNED,
    IN p_estatus BIT(1),
    IN p_category_id INT
)
BEGIN
    DECLARE v_product_id INT UNSIGNED;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    IF p_precio IS NULL OR p_precio <= 0 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Error: El precio del producto debe ser mayor a 0.';
    END IF;

    IF NOT EXISTS (SELECT 1 FROM `tbc_categories` WHERE `ID` = p_category_id) THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Error: La categoría especificada no existe.';
    END IF;

    START TRANSACTION;

    INSERT INTO `tb_products` (
        `SKU`, `name`, `description`, `current_price`, `current_stock`, `status`, `creation_date`
    ) VALUES (
        p_sku, p_nombre, p_descripcion, p_precio, IFNULL(p_stock, 0), IFNULL(p_estatus, b'1'), NOW()
    );

    SET v_product_id = LAST_INSERT_ID();

    -- Corregido a tbd_products_categories
    INSERT INTO `tbd_products_categories` (
        `product_ID`, `category_ID`, `status`, `creation_date`, `last_update`
    ) VALUES (
        v_product_id, p_category_id, b'1', NOW(), NOW()
    );

    COMMIT;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
