/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_simular_usuarios_masivo`(
    IN p_cantidad INT,             -- Obligatorio: cantidad de registros a generar
    IN p_genero VARCHAR(25),       -- Comodín: NULL o '*' aleatorio; o 'Hombre', 'Mujer', 'Prefiero no decirlo'
    IN p_pais VARCHAR(50),         -- Comodín: NULL o '*' aleatorio; o código ISO 'US', 'MX', etc.
    IN p_edad_min INT,             -- Opcional: NULL o 0 toma 18 por defecto
    IN p_edad_max INT,             -- Opcional: NULL o 0 toma 65 por defecto
    IN p_prob_activo INT           -- Opcional: NULL o < 0 toma 100% activos (ej. 80 = 80% activos)
)
BEGIN
    DECLARE v_contador INT DEFAULT 1;
    DECLARE v_edad_ini INT;
    DECLARE v_edad_fin INT;
    DECLARE v_prob INT;
    
    DECLARE v_titulo VARCHAR(20);
    DECLARE v_nombre VARCHAR(150);
    DECLARE v_apellido VARCHAR(150);
    DECLARE v_genero_final VARCHAR(25);
    DECLARE v_pais_final CHAR(2);
    DECLARE v_fecha_nac DATE;
    DECLARE v_telefono VARCHAR(25);
    DECLARE v_estatus BIT(1);
    DECLARE v_nick VARCHAR(50);
    DECLARE v_email VARCHAR(100);
    DECLARE v_user_id INT;
    DECLARE v_sufijo_unico VARCHAR(12);

    DECLARE v_nombres_m TEXT DEFAULT 'Carlos,Luis,Miguel,Juan,Jorge,Andres,Diego,Fernando,Ricardo,Alejandro,David,Daniel,Jose,Eduardo,Roberto';
    DECLARE v_nombres_f TEXT DEFAULT 'Ana,Maria,Sofia,Laura,Valeria,Camila,Fernanda,Daniela,Paula,Andrea,Gabriela,Lucia,Elena,Mariana,Isabel';
    DECLARE v_apellidos TEXT DEFAULT 'Garcia,Hernandez,Martinez,Lopez,Gonzalez,Perez,Rodriguez,Sanchez,Ramirez,Cruz,Flores,Gomez,Morales,Vazquez,Reyes';
    DECLARE v_paises_iso TEXT DEFAULT 'MX,US,CO,AR,ES,CL,PE,BR,CA,DE';

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    IF p_cantidad IS NULL OR p_cantidad <= 0 THEN
        SIGNAL SQLSTATE '45000' 
        SET MESSAGE_TEXT = 'Error: El parámetro p_cantidad debe ser mayor a 0.';
    END IF;

    SET v_edad_ini = IF(p_edad_min IS NULL OR p_edad_min <= 0, 18, p_edad_min);
    SET v_edad_fin = IF(p_edad_max IS NULL OR p_edad_max <= 0, 65, p_edad_max);
    SET v_prob     = IF(p_prob_activo IS NULL OR p_prob_activo < 0 OR p_prob_activo > 100, 100, p_prob_activo);

    IF v_edad_ini > v_edad_fin THEN
        SIGNAL SQLSTATE '45000' 
        SET MESSAGE_TEXT = 'Error: p_edad_min no puede ser mayor que p_edad_max.';
    END IF;

    START TRANSACTION;

    WHILE v_contador <= p_cantidad DO
        -- Normalizar género al ENUM('Hombre','Mujer','Prefiero no decirlo')
        IF p_genero IS NULL OR p_genero = '' OR p_genero = '*' THEN
            SET v_genero_final = CASE fn_entero_aleatorio(1, 10)
                WHEN 1 THEN 'Prefiero no decirlo'
                WHEN 2 THEN 'Hombre'
                WHEN 3 THEN 'Hombre'
                WHEN 4 THEN 'Hombre'
                WHEN 5 THEN 'Hombre'
                ELSE 'Mujer'
            END;
        ELSEIF p_genero IN ('Hombre', 'Masculino', 'M', 'Male') THEN
            SET v_genero_final = 'Hombre';
        ELSEIF p_genero IN ('Mujer', 'Femenino', 'F', 'Female') THEN
            SET v_genero_final = 'Mujer';
        ELSE
            SET v_genero_final = 'Prefiero no decirlo';
        END IF;

        -- Título de cortesía, nombre y apellido
        IF v_genero_final = 'Hombre' THEN
            SET v_titulo = 'Sr.';
            SET v_nombre = fn_elemento_aleatorio(v_nombres_m, 15);
        ELSEIF v_genero_final = 'Mujer' THEN
            SET v_titulo = 'Sra.';
            SET v_nombre = fn_elemento_aleatorio(v_nombres_f, 15);
        ELSE
            SET v_titulo = 'Mx.';
            SET v_nombre = IF(fn_entero_aleatorio(0, 1) = 1, fn_elemento_aleatorio(v_nombres_m, 15), fn_elemento_aleatorio(v_nombres_f, 15));
        END IF;
        SET v_apellido = fn_elemento_aleatorio(v_apellidos, 15);

        -- Normalizar país a CHAR(2)
        IF p_pais IS NULL OR p_pais = '' OR p_pais = '*' THEN
            SET v_pais_final = fn_elemento_aleatorio(v_paises_iso, 10);
        ELSEIF p_pais IN ('Estados Unidos', 'USA', 'US') THEN
            SET v_pais_final = 'US';
        ELSEIF p_pais IN ('Mexico', 'México', 'MX') THEN
            SET v_pais_final = 'MX';
        ELSE
            SET v_pais_final = UPPER(LEFT(TRIM(p_pais), 2));
        END IF;

        -- Fecha de nacimiento, teléfono y estatus probabilístico
        SET v_fecha_nac = fn_generar_fecha_nacimiento(v_edad_ini, v_edad_fin);
        SET v_telefono  = CONCAT('+', fn_entero_aleatorio(1, 59), ' ', fn_entero_aleatorio(200, 999), '-', fn_entero_aleatorio(100, 999), '-', fn_entero_aleatorio(1000, 9999));
        SET v_estatus   = fn_estatus_probabilistico(v_prob);

        -- Nick (<= 50 chars) y Email (<= 100 chars) únicos
        SET v_sufijo_unico = RIGHT(UUID_SHORT(), 8);
        SET v_nick  = LOWER(CONCAT(LEFT(v_nombre, 10), '.', LEFT(v_apellido, 10), '_', v_sufijo_unico));
        SET v_email = CONCAT(v_nick, '@ecommerce-test.com');

        -- Insertar primero en tb_users
        INSERT INTO `tb_users` (
            `email`, `nick`, `password`, `creation_date`, `status`
        ) VALUES (
            v_email, v_nick, SHA2('Pass1234!', 256), NOW(), v_estatus
        );

        SET v_user_id = LAST_INSERT_ID();

        -- Insertar después en tb_people ligando user_ID
        INSERT INTO `tb_people` (
            `user_ID`, `courtesy_title`, `given_names`, `family_names`, `birth_date`, `gender`, `country_code`, `phone`, `status`, `creation_date`
        ) VALUES (
            v_user_id, v_titulo, v_nombre, v_apellido, v_fecha_nac, v_genero_final, v_pais_final, v_telefono, v_estatus, NOW()
        );

        SET v_contador = v_contador + 1;
    END WHILE;

    COMMIT;
END ;;
DELIMITER ;
